// Bundles server/library (built-in skills, knowledge and templates) into
// server/library-data.ts, so they ship inside the single binary.
// `--check` fails when the generated file is out of date (CI).
import { readdirSync, readFileSync, statSync, writeFileSync, existsSync } from "node:fs";
import { join, relative } from "node:path";

const root = join(import.meta.dir, "..", "server", "library");
const out = join(import.meta.dir, "..", "server", "library-data.ts");
const files: Record<string, string> = {};
const walk = (d: string) => {
  for (const e of readdirSync(d).sort()) {
    const p = join(d, e);
    if (statSync(p).isDirectory()) walk(p);
    else if (e.endsWith(".md")) files[relative(root, p).split("\\").join("/")] = readFileSync(p, "utf8");
  }
};
walk(root);
const text = `// Generated by scripts/gen-library.ts from server/library. Do not edit by hand.\nexport const LIBRARY: Record<string, string> = ${JSON.stringify(files, null, 2)};\n`;
if (process.argv.includes("--check")) {
  if (!existsSync(out) || readFileSync(out, "utf8") !== text) {
    console.error("server/library-data.ts is out of date: run bun scripts/gen-library.ts");
    process.exit(1);
  }
  console.log(`library up to date (${Object.keys(files).length} files)`);
} else {
  writeFileSync(out, text);
  console.log(`wrote ${Object.keys(files).length} files into server/library-data.ts`);
}
